//! Checks every function against ../testdata/*.csv (generated by
//! scripts/datecalc.py, itself verified against dateutil, numpy, convertdate,
//! hijridate and sxtwl).
use chrono::{Datelike, NaiveDate, Weekday};
use datecal::calendars::*;
use datecal::recipes::*;
use std::fs;

fn d(s: &str) -> NaiveDate {
    NaiveDate::parse_from_str(s, "%Y-%m-%d").unwrap()
}
fn rows(name: &str) -> Vec<Vec<String>> {
    let path = format!("{}/../testdata/{}", env!("CARGO_MANIFEST_DIR"), name);
    fs::read_to_string(&path)
        .unwrap_or_else(|e| panic!("{path}: {e}"))
        .lines()
        .skip(1)
        .map(|l| l.split(',').map(str::to_string).collect())
        .collect()
}
fn wd(s: &str) -> Weekday {
    s.parse().unwrap()
}

#[test]
fn arithmetic_golden() {
    let mut n = 0;
    for r in rows("arithmetic.csv") {
        let (op, a, b, exp) = (r[0].as_str(), r[1].as_str(), r[2].as_str(), r[3].as_str());
        let got: String = match op {
            "add_months" => add_months(d(a), b.parse().unwrap()).unwrap().to_string(),
            "add_days" => add_days(d(a), b.parse().unwrap()).unwrap().to_string(),
            "nth_weekday" => {
                let (y, m) = a.split_once('-').unwrap();
                let (w, k) = b.split_once(':').unwrap();
                nth_weekday_of_month(y.parse().unwrap(), m.parse().unwrap(), wd(w), k.parse().unwrap())
                    .unwrap()
                    .to_string()
            }
            "next_weekday_strict" => next_weekday(d(a), wd(b)).to_string(),
            "prev_weekday_strict" => prev_weekday(d(a), wd(b)).to_string(),
            "add_business_days" => add_business_days(d(a), b.parse().unwrap()).to_string(),
            "business_days_between" => business_days_between(d(a), d(b)).to_string(),
            "days_between" => days_between(d(a), d(b)).to_string(),
            "iso_week" => {
                let w = d(a).iso_week();
                format!("{}-W{:02}", w.year(), w.week())
            }
            "first_of_next_month" => first_of_next_month(d(a)).to_string(),
            "last_of_month" => last_of_month(d(a)).to_string(),
            "easter_western" => easter_western(a.parse().unwrap()).to_string(),
            "easter_orthodox" => easter_orthodox(a.parse().unwrap()).to_string(),
            _ => panic!("unknown op {op}"),
        };
        assert_eq!(got, exp, "{op}({a}, {b})");
        n += 1;
    }
    assert!(n > 4000);
}

#[test]
fn hebrew_golden() {
    for r in rows("hebrew_month_starts.csv") {
        let n = rd(d(&r[0]));
        let (y, m): (i64, i64) = (r[1].parse().unwrap(), r[2].parse().unwrap());
        assert_eq!(hebrew_from_fixed(n), (y, m, 1), "{}", r[0]);
        assert_eq!(fixed_from_hebrew(y, m, 1), Some(n));
        assert_eq!(hebrew_month_length(y, m), r[4].parse::<i64>().unwrap());
    }
}

#[test]
fn umalqura_golden() {
    for r in rows("hijri_umalqura_month_starts.csv") {
        let n = rd(d(&r[0]));
        let (y, m): (i64, i64) = (r[1].parse().unwrap(), r[2].parse().unwrap());
        assert_eq!(umalqura_from_fixed(n), Some((y, m, 1)));
        assert_eq!(fixed_from_umalqura(y, m, 1), Some(n));
    }
}

#[test]
fn julian_and_tabular_golden() {
    for r in rows("julian_and_tabular_hijri.csv") {
        let n = rd(d(&r[0]));
        let (y, m, dd) = julian_from_fixed(n);
        assert_eq!(format!("{y:04}-{m:02}-{dd:02}"), r[1]);
        assert_eq!(fixed_from_julian(y, m, dd), n);
        let (y, m, dd) = hijri_tabular_from_fixed(n);
        assert_eq!(format!("{y}-{m:02}-{dd:02}"), r[2]);
        assert_eq!(fixed_from_hijri_tabular(y, m, dd), n);
    }
}

#[test]
fn chinese_golden() {
    for r in rows("chinese_month_starts.csv") {
        let n = rd(d(&r[0]));
        let c = ChineseDate {
            year: r[1].parse().unwrap(),
            month: r[2].parse().unwrap(),
            leap: r[3] == "1",
            day: 1,
        };
        assert_eq!(chinese_from_fixed(n), c, "{}", r[0]);
        assert_eq!(fixed_from_chinese(c), Some(n), "{}", r[0]);
        let len: i64 = r[4].parse().unwrap();
        let last = chinese_from_fixed(n + len - 1);
        assert_eq!((last.month, last.leap, i64::from(last.day)), (c.month, c.leap, len), "{}", r[0]);
    }
}
